PROGRAM ST150_PALLETERING
VAR
    steg        : INT := 0;
    raknare     : CTU;
    tmrVac      : TON;
    trigPall    : R_TRIG;
    trigPrt     : R_TRIG;
    xNyPall     : BOOL := FALSE;
    xNyttKolli  : BOOL := FALSE;
    xGivarfel   : BOOL := FALSE;
    xOverHojd   : BOOL := FALSE;
    xGreppfel   : BOOL := FALSE;
    xVakVantar  : BOOL := FALSE;
    xDriftsklar : BOOL := FALSE;
    xRakna      : BOOL := FALSE;
END_VAR

(* Monstret ar pallens och kollits egna matt. EUR-pallen ar 1200 x 800 mm och
   kollit 400 x 300 mm: tva i bredd langs 800 mm-sidan och fyra i djup langs
   1200 mm-sidan ger atta kolli i lagret. Atta ar alltsa inget instalt tal. *)

(* En ny pall i stationen ar ett nytt lager. Utan den nollstallningen bar
   lager tva kvar forra lagrets rakning och blir ett halvt lager. *)
trigPall(CLK := ST150_PLT_PRS);
xNyPall := trigPall.Q;

(* Hamtningen startar pa FLANKEN av narvaron i hamtlaget, inte pa nivan. Pa
   nivan startar cellen om av sig sjalv sa fort ett villkor slapper igen. *)
trigPrt(CLK := ST150_PRT_PRS);
xNyttKolli := trigPrt.Q;

(* EUR-pallen ar sjalv 144 mm hog. En lasthojd under 144 mm med pall i
   stationen ar darfor ett givarfel, inte ett lage. *)
xGivarfel := ST150_PLT_PRS AND (ST150_PLT_HGT < 144.0);

(* Hogsta lasthojd pa pallen ar 1800 mm. Daroever far ingenting mer laggas,
   oavsett vad lagerrakningen sager. *)
xOverHojd := ST150_PLT_HGT > 1800.0;

(* Greppvakt: undertrycket ska vara bekraftat inom 1,0 s. En vantan utan
   tidsgrans lamnar cellen dragande pa ett kolli den inte haller. *)
xVakVantar := ST150_VAC_ON AND NOT ST150_VAC_OK;
tmrVac(IN := xVakVantar, PT := T#1s);
IF tmrVac.Q THEN
    xGreppfel := TRUE;
END_IF;
IF NOT ST150_PRT_PRS THEN
    xGreppfel := FALSE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND ST150_PLT_PRS
               AND NOT xGivarfel AND NOT xOverHojd AND NOT xGreppfel;

xRakna := FALSE;

IF NOT xDriftsklar THEN
    (* Avlaggsordern tas bort i samma scan. Vakuumet star kvar: att slappa
       greppet har ar att tappa kollit fran hojd, i varsta fall over en tom
       station. Bara ett bekraftat greppfel slapper vakuumet. *)
    ST150_RB_START := FALSE;
    IF xGreppfel THEN
        ST150_VAC_ON := FALSE;
    END_IF;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST150_RB_START := FALSE;
            IF xNyttKolli AND NOT ST150_PLT_FULL THEN
                ST150_VAC_ON := TRUE;
                steg := 1;
            END_IF;
        1:
            (* Avlagget kommenderas forst nar undertrycket ar bekraftat. *)
            IF ST150_VAC_OK THEN
                ST150_RB_START := TRUE;
                steg := 2;
            END_IF;
        2:
            (* Vakuumet slapps pa ST150_RB_DONE, alltsa nar kollit star an mot
               underlaget - aldrig pa en hojd. Lasthojdsgivaren ser kollits
               overkant redan medan kollit hanger. *)
            IF ST150_RB_DONE THEN
                ST150_RB_START := FALSE;
                ST150_VAC_ON := FALSE;
                xRakna := TRUE;
                steg := 3;
            END_IF;
        3:
            IF NOT ST150_RB_DONE THEN
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Rakningen gar pa en puls som ar exakt en scan bred, en per lagt kolli. *)
raknare(CU := xRakna, R := xNyPall, PV := 8);
ST150_LYR_CNT := raknare.CV;
ST150_PLT_FULL := raknare.Q OR xOverHojd;
END_PROGRAM

